import { readFileSync } from "node:fs";

const messageFile = process.argv[2];

if (!messageFile) {
  process.exit(0);
}

const rawMessage = readFileSync(messageFile, "utf-8");
const message = rawMessage
  .split("\n")
  .filter((line) => !line.trim().startsWith("#"))
  .join("\n")
  .trim();

// Names of AI assistants/tools that show up in auto-appended attribution.
const aiNames = "ai|chatgpt|gpt|claude|codex|copilot|llm|cursor|anthropic|openai";

// 1. Attribution phrases, e.g. "generated by AI", "co-authored with codex".
const attributionPhrase = new RegExp(
  `\\b(generated|written|created|authored|co-authored|assisted)\\s+(by|with|using)\\s+(${aiNames})\\b`,
  "i",
);

// 2. "Co-Authored-By:" trailer naming an AI tool (the most common auto-append).
const coAuthoredTrailer = new RegExp(`co-authored-by:.*\\b(${aiNames})\\b`, "i");

// 3. Robot emoji used as an attribution marker.
const robotEmoji = /\u{1F916}/u;

// 4. Bracketed link attribution, e.g. "Generated with [Claude Code](...)".
const bracketedAttribution = new RegExp(`generated\\s+with\\s+\\[.*?(${aiNames})`, "i");

const bannedPatterns = [attributionPhrase, coAuthoredTrailer, robotEmoji, bracketedAttribution];

if (bannedPatterns.some((pattern) => pattern.test(message))) {
  console.error(
    'Commit message validation failed: remove AI attribution (e.g. "generated with", Co-Authored-By bot trailers, 🤖) from the commit message.',
  );
  process.exit(1);
}
